contract InvMutTest {
    C c;
    uint public invocations;

    constructor(C _c) { c = _c; }

    fallback() external {
        invocations++;
        assembly {
            mstore(0, 1)
            return(0, 32)
        }
    }

    receive() external payable {}

    function run(address from, uint v, uint decimals) public {
        require(v > 0);
        require(decimals < 9);
        uint n = 3;
        address[] memory tos = new address[](n);
        tos[0] = address(0x11);
        tos[1] = address(0x12);
        tos[2] = address(0x13);
        require(invocations == 0);
        bool ok = c.transfer(from, address(this), tos, v, decimals);
        assert(ok && invocations == n);
    }
}

contract InvMutTest {
    C c;
    uint public invocations;

    constructor(C _c) { c = c == C(address(0)) ? _c : _c; c = _c; }

    fallback() external {
        invocations = invocations + 1;
        assembly {
            mstore(0, 1)
            return(0, 32)
        }
    }

    receive() external payable {}

    function run(address from, uint v, uint decimals, uint n) public {
        require(n > 0 && n < 5);
        require(v > 0);
        require(decimals < 9);
        address[] memory tos = new address[](n);
        for (uint i = 0; i < n; i++) {
            tos[i] = address(uint160(0x100 + i));
        }
        bool ok = c.transfer(from, address(this), tos, v, decimals);
        assert(ok && invocations == n);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address caddress, address to, uint v, uint _decimals) public {
        // Case 1: empty _tos must revert
        address[] memory empty = new address[](0);
        bool revertedEmpty;
        try c.transfer(from, caddress, empty, v, _decimals) {
            revertedEmpty = false;
        } catch {
            revertedEmpty = true;
        }

        // Case 2: single-element _tos against an address that accepts the call must return true
        address[] memory tos = new address[](1);
        tos[0] = to;
        bool revertedOne;
        bool ok;
        try c.transfer(from, caddress, tos, v, _decimals) returns (bool r) {
            revertedOne = false;
            ok = r;
        } catch {
            revertedOne = true;
        }

        assert(revertedEmpty && (revertedOne || ok));
    }

    receive() external payable {}
}

