contract InvMutTest {
    C c;
    bytes4 constant XF = bytes4(keccak256("transferFrom(address,address,uint256)"));
    constructor(C _c) { c = _c; }
    function run(address from, address[] memory tos, uint v, uint dec) public {
        require(tos.length > 0);
        require(v <= 10 ** 30);
        require(dec <= 30);
        require(v * (10 ** dec) / (10 ** dec) == v);
        bool ok;
        bytes memory ret;
        (ok, ret) = address(c).call(abi.encodeWithSelector(c.transfer.selector, from, address(this), tos, v, dec));
        assert(ok && ret.length == 32 && abi.decode(ret, (bool)));
    }
    fallback() external payable returns (bool) {
        if (msg.sig == XF && msg.data.length == 100) {
            assembly { mstore(0x00, 0x01) return(0x00, 0x20) }
        }
        return false;
    }
    receive() external payable {}
}

